                                    tracing::trace!(



                                        "Successfully parsed override flag: {}, new filters: {:?}",



                                        flag_key,



                                        override_flag.filters



                                    );







                                    let original_key = flag.key.clone();



                                    let original_id = flag.id;



                                    let original_team_id = flag.team_id;







                                    if override_flag.key != original_key



                                        || override_flag.id != original_id



                                        || override_flag.team_id != original_team_id



                                    {



                                        tracing::warn!(



                                            "Override definition for flag {} attempted to change identity fields (override key: {}, id: {}, team_id: {}; original key: {}, id: {}, team_id: {}); preserving original identity",



                                            flag_key,



                                            override_flag.key,



                                            override_flag.id,



                                            override_flag.team_id,



                                            original_key,



                                            original_id,



                                            original_team_id



                                        );



                                    }







                                    override_flag.key = original_key;



                                    override_flag.id = original_id;



                                    override_flag.team_id = original_team_id;

